(function(){
'use strict';
const D=ATLAS,U=AtlasDomain,$=s=>document.querySelector(s),E=U.esc;
const state={city:'taipei',tab:'candidates',year:2022,person:null,region:'cn'};
const parties={KMT:'中国国民党',DPP:'民主进步党'},labels={cn:'两岸 / 中国大陆',us:'美国',jp:'日本'},dialog=$('#dossier');
const partyClass=p=>p==='KMT'?'kmt':p==='DPP'?'dpp':'';
const badge=p=>`<span class="party ${partyClass(p)}">${E(parties[p]||p)}</span>`;
const num=n=>new Intl.NumberFormat('zh-CN').format(n);
function src(id,label){return AtlasMedia.render(id,label);}
function city(){return D.cities.find(c=>c.id===state.city);}
function selectCity(id){if(D.cities.some(c=>c.id===id))location.hash='/'+id;}
function renderCities(){for(const sel of ['#city-switch','#history-cities'])$(sel).innerHTML=D.cities.map(c=>`<button data-select-city="${c.id}" aria-pressed="${c.id===state.city}">${c.name}</button>`).join('');}
function renderCity(){const c=city(),n=D.people.filter(p=>p.city===c.id).length;document.title=`${c.name} · 岛屿选战`;renderCities();AtlasMap.select(c.id);$('.edition b').textContent=c.index+' / 05';$('#city-heading').innerHTML=`<div class="city-title"><div><h2>${c.name}</h2><div class="en">${c.en}</div></div><div class="city-count"><strong>${String(n).padStart(2,'0')}</strong><span>登记参选人</span></div></div><p class="city-caption">${c.caption}</p>`;renderPanel();renderHistory();window.AtlasResearch?.renderCity(state.city);AtlasPolicies.render(state.city);}
function normalize(v){const a='蔣萬蘇輝湟蕭啟陳賴龍燐麗謝郭張葉柯純靜豐縣臺',b='蒋万苏辉湟萧启陈赖龙燐丽谢郭张叶柯纯静丰县台';return v.toLowerCase().replace(/[蔣萬蘇輝湟蕭啟陳賴龍燐麗謝郭張葉柯純靜豐縣臺]/g,c=>b[a.indexOf(c)]);}
function renderCandidates(query=''){const list=D.people.filter(p=>p.city===state.city&&normalize(p.name+' '+p.bio+' '+(parties[p.party]||p.party)).includes(normalize(query)));$('#candidate-list').innerHTML=list.length?list.map(p=>`<button class="candidate-row" data-person="${p.id}" aria-label="查看${E(p.name)}档案">${AtlasProfiles.portrait(p)}<span class="candidate-main"><span class="candidate-name">${E(p.name)}</span>${badge(p.party)}<span class="candidate-role" style="display:block">${E(p.bio)}</span></span><span class="row-arrow" aria-hidden="true">↗</span></button>`).join(''):'<div class="no-results">本市没有匹配的已收录参选人。请尝试姓名或党籍。</div>';}
function results(e,mini=false){const allPercent=e.rows.every(r=>U.percent(r,e)!==null),max=Math.max(...e.rows.map(r=>r[2]));return `<div class="${mini?'mini-results':''}">${e.rows.map(r=>{const p=U.percent(r,e),width=allPercent?p:r[2]/max*100;return `<div class="result-row"><div class="result-label"><span>${E(r[0])}${badge(r[1])}</span><b>${num(r[2])}<small>${p===null?'票':p.toFixed(2)+'%'}</small></b></div><div class="bar-track" aria-hidden="true"><div class="bar-fill ${partyClass(r[1])}" style="width:${width.toFixed(4)}%"></div></div></div>`;}).join('')}<p class="results-note">${E(e.scope)}。${allPercent?'百分比为当届得票率，完整记录按有效票合计计算。':'条长以本组最高票数归一化，不是得票率。'}<br>实际选举结果，不代表2026年支持率。</p><div class="source-line">${e.sources.map(s=>src(s)).join('')}</div></div>`;}
function renderPanel(){document.querySelectorAll('[data-tab]').forEach(b=>{const on=b.dataset.tab===state.tab;b.setAttribute('aria-selected',on);b.tabIndex=on?0:-1;});$('#panel-content').setAttribute('aria-labelledby','tab-'+state.tab);
if(state.tab==='candidates'){$('#panel-content').innerHTML='<label class="candidate-search"><input id="candidate-search" type="search" aria-label="查找本市参选人" placeholder="查找本市参选人或党籍…" autocomplete="off"></label><a class="outline-button" href="#policies">按议题对比政见 ↓</a><div id="candidate-list"></div><div class="source-line">'+src('roster','查看登记资料与经历来源')+'</div>';renderCandidates();$('#candidate-search').addEventListener('input',e=>renderCandidates(e.target.value));}
else if(state.tab==='polls'){$('#panel-content').innerHTML=AtlasMap.polls(state.city)+`<div class="note">以下是2022年的实际选票，不是本届调查。</div><h3 style="font-weight:400;font-size:16px;margin:23px 0">2022 · ${city().name}市长选举</h3>${results(D.elections.find(e=>e.city===state.city&&e.year===2022),true)}`;}
else{$('#panel-content').innerHTML=`<div class="empty-state"><span class="eyebrow">THE CITY BEFORE THE CITY</span><h3>把辖区和时代分开看。</h3><p>${E(city().history)}</p><div class="note">时间轴暂未补齐民主化以来的所有届次。缺失年份标记为待核验，不填入模拟票数。</div><div class="source-line">${src('merger','县市改制沿革')}${src('cec','官方历届资料')}</div><a href="#history" class="outline-button">进入历届票箱 <span>↓</span></a></div>`;}}
function renderHistory(){if(state.city==='taipei'&&window.AtlasResearch){window.AtlasResearch.renderHistory(state.year,results,src);return;}const c=city(),e=D.elections.find(e=>e.city===c.id&&e.year===state.year),years=[1951,1994,2002,2010,2014,2018,2022,2026];$('#timeline').innerHTML=years.map(y=>`<button data-year="${y}" aria-pressed="${y===state.year}">${y===1951?'1950/51':y}<small>${y===1951?'地方民选':y===1994?'制度节点':y===2026?'本届':D.elections.some(e=>e.city===state.city&&e.year===y)?'已录票数':'待核验'}</small></button>`).join('');
const title=state.year===1951?'1950/51':state.year,summary=`<div class="history-summary"><div class="year-big">${title}</div><h3>${c.name} · ${state.year===1951||state.year===1994?'制度档案':'历届票箱'}</h3><span class="record-badge">${e?(e.complete?'本届票数已齐':'本届部分资料'):state.year===2026?'尚未投票':'历史资料节点'}</span><p>${e?'一届一份档案，记录当时的党籍和选票。不把后来的政治身份倒填回过去。':E(c.history)}</p></div>`;
let body;if(e)body=(e.narrative?`<div class="history-evidence"><article class="history-narrative"><h4>${E(e.narrative.title)}</h4><p>${E(e.narrative.text)}</p><p>投票率 ${e.turnout.toFixed(2)}% · 选举人数 ${num(e.eligibleVoters)}人</p><p class="research-check">${E(e.verification)}</p></article>${results(e)}</div>`:results(e));else if(state.year===1951)body=`<div class="history-empty"><span class="eyebrow">LOCAL ELECTIONS ≠ FULL DEMOCRATIZATION</span><h3>有了地方选举，不等于完成民主化。</h3><p>首届县市长选举在1950至1951年间分期举行。地方首长的民选史与后来的民主化进程，需要分别说明。本版还未逐城导入这些早期票数。</p><p>官派任期将保留为时间轴间隔，不列作投票结果。</p>${src('local51')}</div>`;else if(state.year===1994)body=`<div class="history-empty"><span class="eyebrow">INSTITUTIONAL RECORD</span><h3>1994 · 直辖市自治法</h3><p>1994年7月29日公布的直辖市自治法，是此处收录的制度文献。该节点不是五座城市同年、同制度选举的意思。各市当届票数仍待分别核对。</p>${src('statute94')}</div>`;else if(state.year===2026)body=`<div class="history-empty"><h3>2026.11.28 · 这一届，尚未投票。</h3><p>本届登记参选人已经收录。没有开票结果，便不放模拟数字；没有完成核查的民调，便不借历史票数代替。</p>${src('roster','日期与登记资料')}<p><button class="outline-button" id="back-current">回到本届参选人 <span>↑</span></button></p></div>`;else body=`<div class="history-empty"><span class="eyebrow">NOT YET TRANSCRIBED</span><h3>这一页，等待证据补齐。</h3><p>${state.year}年的${c.name}相关选举资料尚未完成逐项核对。这里的空白不代表当年没有选举，也不会沿用其他年份的数据。</p>${src('cec','前往官方选举资料库')}</div>`;$('#history-content').innerHTML=summary+body;if(matchMedia('(max-width:600px)').matches){const rail=$('#timeline'),active=rail.querySelector('[aria-pressed="true"]');rail.scrollLeft=active.offsetLeft-rail.offsetLeft-rail.clientWidth/2+active.clientWidth/2;}}
function openPerson(id){const p=D.people.find(p=>p.id===id);if(!p)return;state.person=id;state.region='cn';document.title=p.name+' · 人物档案 · 岛屿选战';const c=city();$('#dialog-content').innerHTML=`<div class="profile-hero">${AtlasProfiles.portrait(p,'hero')}<div><div class="eyebrow">${c.en} / 2026</div><h2 id="dialog-title">${E(p.name)}</h2>${badge(p.party)}<p>登记资料快照：${D.rosterAsOf}</p></div></div><p class="profile-intro">${E(p.bio)}</p><p class="muted" style="font-size:10px">${E(p.status)}。经历按来源发布时点记录。</p><div class="profile-actions">${src(p.source,'身份与经历来源')}<button class="outline-button" id="copy-link">复制档案链接 ↗</button></div>${AtlasProfiles.photoCredit(p)}${AtlasPolicies.profile(p)}<section class="profile-section"><h3>向外看：三份言行记录</h3><p>按议题查看有日期的表态与行动，不提供“亲谁”分数。资料覆盖范围因人而异；每条记录均注明日期与来源，不用于人物评分。</p><div class="region-tabs" role="group" aria-label="选择对外关系方向">${Object.entries(labels).map(([k,v])=>`<button data-region="${k}" aria-pressed="${k==='cn'}">${v}</button>`).join('')}</div><div id="evidence-content"></div></section><section class="profile-section"><h3>争议与核查</h3><p>数量反映本版的收录进度，不代表人物的争议程度或清白证明。</p>${p.controversies.length?p.controversies.map(v=>`<article class="evidence-card"><span class="state">${E(v.status)}</span><time>${v.date}</time><h4>${E(v.title)}</h4><div class="event-line"><span>${E(v.claimLabel||'请求 / 指控')}</span><p>${E(v.claim)}</p></div><div class="event-line"><span>已知结论</span><p>${E(v.outcome)}</p></div><div class="event-line"><span>本人回应</span><p>${E(v.reply)}</p></div><p class="limit">${E(v.limit)}</p>${(v.sources||[v.source]).map(id=>src(id)).join('')}</article>`).join(''):'<div class="empty-state"><h3>暂未收录完成核查的事件。</h3><p>需要原始依据、回应和后续进展。未收录不代表没有争议，不能据此与其他人物比较。</p></div>'}</section><section class="profile-section"><p>已建档照片随网站保存；出处、图像年代与许可或引用说明见档案上方。<button class="text-button source-open">查看资料标准 ↗</button></p></section>`;renderEvidence();window.AtlasResearch?.renderPerson(p);if(!dialog.open)dialog.showModal();}
function renderEvidence(){const p=D.people.find(p=>p.id===state.person);if(!p)return;const records=p.evidence.filter(e=>e.region===state.region),review=p.evidenceCoverage?.[state.region];document.querySelectorAll('[data-region]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.region===state.region));$('#evidence-content').innerHTML=records.length?records.map(v=>`<article class="evidence-card"><time>${E(v.date)}</time><h4>${E(v.topic)}</h4><p>${E(v.text)}</p><p class="limit">${E(v.limit)}</p>${(v.sources||[v.source]).map(id=>src(id)).join('')}</article>`).join(''):review?`<article class="evidence-card evidence-review"><time>查阅 ${E(review.checkedAt)}</time><h4>已查材料中尚未找到明确表态</h4><p>${E(review.scope)}</p><p class="limit">${E(review.note)}</p>${AtlasMedia.refs(review.sources)}</article>`:`<div class="empty-state"><h3>这条证据线尚未补齐。</h3><p>尚未完成对${labels[state.region]}相关公开言行的核查。不会从党籍、留学经历或合影自动推断立场。</p></div>`;}
function applyRoute(){if(location.hash&&!location.hash.startsWith('#/'))return;const r=U.route(location.hash,D);state.city=r.city;const old=state.person;state.person=r.person;renderCity();if(r.person)openPerson(r.person);else if(dialog.open)dialog.close();}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('visible');setTimeout(()=>$('#toast').classList.remove('visible'),2600);}
document.addEventListener('click',async e=>{const cityButton=e.target.closest('[data-select-city]');if(cityButton){selectCity(cityButton.dataset.selectCity);return;}const person=e.target.closest('[data-person]');if(person){location.hash='/'+state.city+'/'+person.dataset.person;return;}const tab=e.target.closest('[data-tab]');if(tab){state.tab=tab.dataset.tab;renderPanel();return;}const year=e.target.closest('[data-year]');if(year){state.year=Number(year.dataset.year);renderHistory();AtlasMap.update(state.year);return;}const region=e.target.closest('[data-region]');if(region){state.region=region.dataset.region;renderEvidence();return;}if(e.target.closest('.source-open')){$('#sources-dialog').showModal();return;}if(e.target.closest('#back-current')){state.tab='candidates';renderPanel();$('#city-panel').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'auto':'smooth'});}if(e.target.closest('#copy-link')){try{await navigator.clipboard.writeText(location.href);toast('已复制人物档案链接。');}catch{toast('当前环境无法复制，请从地址栏复制链接。');}}});
$('.panel-tabs').addEventListener('keydown',e=>{const tabs=[...document.querySelectorAll('[data-tab]')],i=tabs.indexOf(document.activeElement);if(i<0)return;let next;if(e.key==='ArrowRight')next=(i+1)%tabs.length;else if(e.key==='ArrowLeft')next=(i+tabs.length-1)%tabs.length;else if(e.key==='Home')next=0;else if(e.key==='End')next=tabs.length-1;else return;e.preventDefault();state.tab=tabs[next].dataset.tab;renderPanel();tabs[next].focus();});
$('#close-dialog').onclick=()=>dialog.close();dialog.addEventListener('close',()=>{if(state.person){state.person=null;history.replaceState(null,'','#/'+state.city);document.title=city().name+' · 岛屿选战';}});$('#close-sources').onclick=()=>$('#sources-dialog').close();for(const d of [dialog,$('#sources-dialog')])d.addEventListener('click',e=>{if(e.target===d){const b=d.getBoundingClientRect();if(e.clientX<b.left||e.clientX>b.right||e.clientY<b.top||e.clientY>b.bottom)d.close();}});
$('#source-list').innerHTML=AtlasMedia.room();
const mergerSource=$('#guide-merger-source');if(mergerSource)mergerSource.innerHTML=AtlasMedia.render('merger','县市改制沿革来源');
setInterval(()=>{AtlasMap.update();if(state.tab==='polls')renderPanel();},60000);
AtlasMap.init(id=>{selectCity(id);if(matchMedia('(max-width:950px)').matches)setTimeout(()=>$('#city-panel').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'auto':'smooth'}),80);});window.addEventListener('hashchange',applyRoute);applyRoute();
})();
